from __future__ import annotations

import hashlib
import json
from pathlib import Path
from typing import Any


def _parse_scalar(text: str) -> Any:
    s = text.strip()
    if s == "" or s in ("null", "~", "None"):
        return None
    if s in ("true", "True"):
        return True
    if s in ("false", "False"):
        return False
    if (s.startswith('"') and s.endswith('"')) or (
        s.startswith("'") and s.endswith("'")
    ):
        return s[1:-1]
    try:
        return int(s)
    except ValueError:
        pass
    try:
        return float(s)
    except ValueError:
        pass
    return s


def _mini_yaml(text: str) -> dict[str, Any]:
    """æœ€å°?YAML å­é›†: ç¼©è¿›æ˜ å°„ (2 ç©ºæ ¼/å±? + æ ‡é‡; æ— åˆ—è¡?é”šç‚¹/å¤šè¡Œã€?""
    root: dict[str, Any] = {}
    stack: list[tuple[int, dict[str, Any]]] = [(-1, root)]
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].rstrip()
        if not line.strip():
            continue
        indent = len(line) - len(line.lstrip(" "))
        if ":" not in line:
            raise ValueError(f"config è§£æžå¤±è´¥ (æœ€å°å­é›†ä¸æ”¯æŒ): {raw!r}")
        key, _, rest = line.strip().partition(":")
        while stack and indent <= stack[-1][0]:
            stack.pop()
        parent = stack[-1][1]
        if rest.strip() == "":
            child: dict[str, Any] = {}
            parent[key.strip()] = child
            stack.append((indent, child))
        else:
            parent[key.strip()] = _parse_scalar(rest)
    return root


def load_config(path: str | Path) -> dict[str, Any]:
    """è¯»å– config.yaml â†?dict; é™„åŠ  _config_sha256 (å†…å®¹æŒ‡çº¹, å…¥è¿è¡Œäº§ç‰?ã€?""
    path = Path(path)
